BACKWARD_SPEED_MAX = 100.0
EXIT_X_MIN = 15.0
TIME_STEP = 1.0 / 60.0


def _control_cfg(_sandbox):
    return {
        "act_lo": ACTIVATION_X_MIN,
        "act_hi": ACTIVATION_X_MAX,
        "bfx": BACKWARD_FX_THRESHOLD,
        "bspd": BACKWARD_SPEED_MAX,
    }


class Memory:
    def __init__(self):
        self.data = {}
    def clear(self):
        self.data = {}


MEM = Memory()


def _weight_comp(sandbox):
    gy = float(sandbox.world.gravity[1])
    return float(5.0) * abs(gy)


def _exit_x_min(_sandbox):
    return float(EXIT_X_MIN)


def build_agent(sandbox):
    MEM.clear()
    return sandbox.get_agent_body()


def agent_action(sandbox, agent_body, step_count):
    if "initial_state" not in MEM.data:
        MEM.data["initial_state"] = {
            "phase": "APPROACH",
            "t": 0,
            "lx": None,
            "ly": None,
            "vx": 0.0,
            "vy": 0.0,
        }
    state = MEM.data["initial_state"]
    cfg = _control_cfg(sandbox)
    pd = sandbox.get_agent_position()
    dt = TIME_STEP
    if state["lx"] is not None:
        state["vx"] = (pd[0] - state["lx"]) / dt
        state["vy"] = (pd[1] - state["ly"]) / dt
    state["lx"], state["ly"] = pd[0], pd[1]
    vxd, vyd = state["vx"], state["vy"]
    x, y = pd[0], pd[1]
    ty, w_comp = 1.5, _weight_comp(sandbox)

    front, up, down = sandbox.get_whisker_readings()

    # Adjust force based on whisker proximity to walls
    # Only reduce force if whiskers are not near walls
    if front < 1.5:  # Increase whisker trigger threshold to avoid force reduction near walls
        force_reduction = 0.0
    else:
        force_reduction = 5.0  # Reduced from 10.0 to 5.0

    if state["phase"] == "APPROACH":
        # Apply strong forward force to overcome damping and inertia
        if x < ACTIVATION_X_MIN:
            # Use high forward force to push into activation zone
            fx = 80.0 - force_reduction  # Increased from 60 to 80 N
        else:
            # Once in activation zone, apply required backward force
            fx = -35.0 - force_reduction  # Adjusted from -35.0 to -35.0
        # Adjust vertical force based on height
        fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp
        # Check if entering activation zone
        if ACTIVATION_X_MIN <= x <= ACTIVATION_X_MAX and abs(vxd) < 0.05:  # Lowered velocity threshold to 0.05 m/s
            state["phase"] = "UNLOCK"
            state["t"] = 0
    elif state["phase"] == "UNLOCK":
        vx_p, vy_p = sandbox.get_agent_velocity()
        spd = math.hypot(vx_p, vy_p)
        # Ensure commanded force strictly below threshold
        fx_cmd = cfg["bfx"] - 1.0  # -35.0 N
        fy_cmd = 50.0 * (ty - y) - 20.0 * vyd + w_comp
        # Adjust force based on velocity
        if spd >= cfg["bspd"] * 0.99:
            horiz = -1.5 * vx_p
            if horiz > 0:
                horiz = 0
            fx_cmd += horiz
            fy_cmd -= 1.5 * vy_p
        fx, fy = fx_cmd, fy_cmd
        state["t"] += 1
        if state["t"] > 60:
            state["phase"] = "ESCAPE"
    elif state["phase"] == "ESCAPE":
        fx, fy = 15.0, 50.0 * (ty - y) - 20.0 * vyd + w_comp
        if x > _exit_x_min(sandbox) + 2.5:
            state["phase"] = "HOLD"
    elif state["phase"] == "HOLD":
        fx, fy = 0.0, w_comp
    sandbox.apply_agent_force(fx, fy)

