    pd = sandbox.get_agent_position()
    dt = TIME_STEP
    if state["lx"] is not None:
        state["vx"] = (pd[0] - state["lx"]) / dt
        state["vy"] = (pd[1] - state["ly"]) / dt
    state["lx"], state["ly"] = pd[0], pd[1]
    vxd, vyd = state["vx"], state["vy"]
    x, y = pd[0], pd[1]
    ty, w_comp = 1.5, _weight_comp(sandbox)

    front, up, down = sandbox.get_whisker_readings()
    if front < WHISKER_TRIGGER_THRESHOLD:
        # Reduce force when near walls to prevent stalling
        fx = 60.0  # Reduced from 100 N to 60 N when near walls
    else:
        # Apply moderate forward force when not near walls
        fx = 120.0  # Increased from 60 N to 120 N when not near walls

    if state["phase"] == "APPROACH":
        # Apply forward force based on whisker readings
        if x < ACTIVATION_X_MIN:
            # Use reduced forward force to avoid stalling
            fx = 60.0 if front < WHISKER_TRIGGER_THRESHOLD else 120.0
        else:
            # Once in activation zone, apply required backward force
            fx = -35.0
        # Adjust vertical force based on height
        fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp
        # Check if entering activation zone
        if ACTIVATION_X_MIN <= x <= ACTIVATION_X_MAX and abs(vxd) > 0.2:  # Lowered velocity threshold to 0.2 m/s
            state["phase"] = "UNLOCK"
            state["t"] = 0
    elif state["phase"] == "UNLOCK":
        vx_p, vy_p = sandbox.get_agent_velocity()
        spd = math.hypot(vx_p, vy_p)
        # Ensure commanded force strictly below threshold
        fx_cmd = cfg["bfx"] - 1.0  # -35.0 N
        fy_cmd = 50.0 * (ty - y) - 20.0 * vyd + w_comp
        # Adjust force based on velocity
        if spd >= cfg["bspd"] * 0.99:
            horiz = -1.5 * vx_p
            if horiz > 0:
                horiz = 0
            fx_cmd += horiz
            fy_cmd -= 1.5 * vy_p
        fx, fy = fx_cmd, fy_cmd
        state["t"] += 1
        if state["t"] > 60:
            state["phase"] = "ESCAPE"
    elif state["phase"] == "ESCAPE":
        fx, fy = 15.0, 50.0 * (ty - y) - 20.0 * vyd + w_comp
        if x > _exit_x_min(sandbox) + 2.5:
            state["phase"] = "HOLD"
    elif state["phase"] == "HOLD":
        fx, fy = 0.0, w_comp
    sandbox.apply_agent_force(fx, fy)
